const domains = userCounts.data || [];
const inactive = recentUsers.data || [];
const total = domains.reduce((s, d) => s + d.users, 0);
const inactivePercent = total ? Math.round(inactive.length * 1000 / total) / 10 : 0;
const status = inactive.length === 0 ? 'healthy' : (inactivePercent > 25 ? 'needs attention' : 'ok');
return { version: 'v2', status, inactivePercent, topDomain: domains[0] ? domains[0].domain : null, domains, inactiveUsers: inactive.map(u => ({ name: u.name, email: u.email })) };
